  workspaceMember(filter: {id: {eq: $objectRecordId}}) {
    __typename
    accountOwnerForCompanies {
      edges {
        node {
          __typename
          domainName {
            primaryLinkUrl
            primaryLinkLabel
            secondaryLinks {
              label
              url
              __typename
            }
            __typename
          }
          id
          name
        }
        __typename
      }
      __typename
    }
    agentChatThreadParticipants {
      edges {
        node {
          __typename
          id
        }
        __typename
      }
      __typename
    }
    agentChatThreads {
      edges {
        node {
          __typename
          id
          title
        }
        __typename
      }
      __typename
    }
    assignedAgentChatThreads {
      edges {
        node {
          __typename
          id
          title
        }
        __typename
      }
      __typename
    }
    assignedTasks {
      edges {
        node {
          __typename
          id
          title
        }
        __typename
      }
      __typename
    }
    avatarUrl
    blocklist {
      edges {
        node {
          __typename
          handle
          id
        }
        __typename
      }
      __typename
    }
    calendarEventParticipants {
      edges {
        node {
          __typename
          handle
          id
        }
        __typename
      }
      __typename
    }
    calendarStartDay
    colorScheme
    createdAt
    createdBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
    dateFormat
    deletedAt
    id
    jobTitle
    locale
    messageParticipants {
      edges {
        node {
          __typename
          handle
          id
        }
        __typename
      }
      __typename
    }
    name {
      firstName
      lastName
      __typename
    }
    numberFormat
    openRecordIn
    ownedOpportunities {
      edges {
        node {
          __typename
          id
          name
        }
        __typename
      }
      __typename
    }
    position
    timeFormat
    timelineActivities {
      edges {
        node {
          __typename
          id
          linkedRecordCachedName
        }
        __typename
      }
      __typename
    }
    timeZone
    uiScale
    updatedAt
    updatedBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
